func:
// ตารางช่องจอดของทุกกล้อง (แก้ที่นี่ที่เดียว แล้วกด Deploy)
// x1-x2 = ช่วงจุดกึ่งกลางกล่องรถ เป็นสัดส่วนของความกว้างภาพ (0-1)
flow.set("CAMS", {
  "2A-C01": [
    {id: "01", x1: 0.00, x2: 0.33, type: "pwd"},
    {id: "02", x1: 0.33, x2: 0.67, type: "normal"},
    {id: "03", x1: 0.67, x2: 1.00, type: "normal"}
  ],
  "2A-C02": [
    {id: "04", x1: 0.00, x2: 0.65, type: "pwd"},
    {id: "05", x1: 0.65, x2: 1.00, type: "normal"}
  ],
  "2A-C03": [
    {id: "06", x1: 0.00, x2: 0.33, type: "normal"},
    {id: "07", x1: 0.33, x2: 0.66, type: "normal"},
    {id: "08", x1: 0.66, x2: 1.00, type: "normal"}
  ],
  // เว็บแคมจับโมเดลลานจอดจำลอง -> CiRA MQTT Pub topic: parking/raw/2A-C04
  // ภาพแนวนอน: 2 แถว x 6 ช่อง (แถวบน 09-14, แถวล่าง 15-20) ถนนตรงกลาง y 0.40-0.60 ไม่นับ
  // ค่าประมาณจากภาพ Debug ของเว็บแคม -> ถ้าขยับกล้อง/แผ่นลานจอด ให้ปรับ x/y ใหม่
  "2A-C04": [
    // แถวบน ซ้าย->ขวา
    {id: "09", x1: 0.07, x2: 0.19, y1: 0.00, y2: 0.40, type: "normal"},
    {id: "10", x1: 0.19, x2: 0.30, y1: 0.00, y2: 0.40, type: "normal"},
    {id: "11", x1: 0.30, x2: 0.40, y1: 0.00, y2: 0.40, type: "normal"},
    {id: "12", x1: 0.40, x2: 0.51, y1: 0.00, y2: 0.40, type: "normal"},
    {id: "13", x1: 0.51, x2: 0.61, y1: 0.00, y2: 0.40, type: "normal"},
    {id: "14", x1: 0.61, x2: 0.75, y1: 0.00, y2: 0.40, type: "normal"},
    // แถวล่าง ซ้าย->ขวา
    {id: "15", x1: 0.06, x2: 0.20, y1: 0.60, y2: 1.00, type: "normal"},
    {id: "16", x1: 0.20, x2: 0.30, y1: 0.60, y2: 1.00, type: "normal"},
    {id: "17", x1: 0.30, x2: 0.42, y1: 0.60, y2: 1.00, type: "normal"},
    {id: "18", x1: 0.42, x2: 0.52, y1: 0.60, y2: 1.00, type: "normal"},
    {id: "19", x1: 0.52, x2: 0.63, y1: 0.60, y2: 1.00, type: "normal"},
    {id: "20", x1: 0.63, x2: 0.78, y1: 0.60, y2: 1.00, type: "normal"}
  ]
});
// ชื่อชั้นที่แสดงบน dashboard / ป้าย LCD
flow.set("LABEL", {"2A-C01": "Floor 1", "2A-C02": "Floor 2", "2A-C03": "Floor 3", "2A-C04": "Floor 4"});
flow.set("lastSeen", {});
flow.set("camStats", {});
flow.set("offline", {});
flow.set("slotState", {});
return null;

// DeepDetect -> สถานะช่อง (dedupe + debounce) -> MQTT
const CAMS = flow.get("CAMS");
if (!CAMS || !msg.topic) return null;
const cam = msg.topic.split("/")[2];
const slots = CAMS[cam];
if (!slots) return null;
const zone = cam.split("-")[0];

const root = msg.payload && (msg.payload.payload || msg.payload);
const dd = root && root.DeepDetect;
if (!dd) return null;

const CONF = 0.5;
const MARGIN = 0.10;
// ชื่อ class จากโมเดล (รองรับทั้งโมเดลเดิม Occupied/Avalible และโมเดลใหม่ occupied/empty)
const OCC_NAMES = ["occupied", "car"];
const FREE_NAMES = ["avalible", "available", "empty", "free"];
const DEBOUNCE_MS = msg.sim ? 0 : 5000;
const W = dd.im_w || 1920;
const H = dd.im_h || 1080;

const seen = flow.get("lastSeen") || {};
const off = flow.get("offline") || {};
const states = context.get("state") || {};

// กล้องกลับมาออนไลน์ -> เริ่มตัดสินใหม่
if (off[cam]) {
  for (const s of slots) delete states[cam + "-" + s.id];
  off[cam] = false;
  flow.set("offline", off);
}
seen[cam] = Date.now();
flow.set("lastSeen", seen);

// สุขภาพกล้อง: fps, ความมั่นใจเฉลี่ย, กล่องที่ตรวจจับ (ให้ dashboard วาด "มุมมอง AI")
const H0 = dd.im_h || 1080;
const cstat = flow.get("camStats") || {};
const cs0 = cstat[cam] || {n: 0};
const tnow = Date.now();
if (cs0.last) { const f = 1000 / Math.max(tnow - cs0.last, 1); cs0.fps = cs0.fps ? cs0.fps * 0.85 + f * 0.15 : f; }
cs0.last = tnow; cs0.n++;
const objs = dd.objects || [];
cs0.conf = objs.length ? objs.reduce((a, o) => a + o.confidence, 0) / objs.length : null;
cs0.ar = W / H0;
cs0.boxes = objs.slice(0, 40).map(o => ({x: +(o.x / W).toFixed(4), y: +(o.y / H0).toFixed(4),
  w: +((o.w || 0) / W).toFixed(4), h: +((o.h || 0) / H0).toFixed(4), n: OCC_NAMES.includes(String(o.name || "").toLowerCase()) ? "Occupied" : "Available", c: +o.confidence.toFixed(2)}));
cstat[cam] = cs0;
flow.set("camStats", cstat);

const out = [];
for (const s of slots) {
  // หลายกล่องในช่องเดียว (โมเดลตรวจซ้ำ) -> เอา confidence สูงสุดของแต่ละ class
  let occ = 0, avl = 0;
  for (const o of (dd.objects || [])) {
    const cx = o.x / W;                 // x = จุดกึ่งกลางกล่อง
    if (cx < s.x1 || cx >= s.x2) continue;
    // ช่องที่มี y1/y2 (กล้องมองด้านบน) -> เช็คแกน y ด้วย
    if (s.y1 !== undefined) {
      const cy = o.y / H;
      if (cy < s.y1 || cy >= s.y2) continue;
    }
    const nm = String(o.name || "").toLowerCase();
    if (OCC_NAMES.includes(nm)) occ = Math.max(occ, o.confidence);
    else if (FREE_NAMES.includes(nm)) avl = Math.max(avl, o.confidence);
  }
  // กล่อง occupied/empty ซ้อนกันในช่องเดียว -> ต้องชนะกันอย่างน้อย MARGIN ไม่งั้นคงสถานะเดิม
  let status = null;
  if (occ >= CONF && occ - avl >= MARGIN) status = "occupied";
  else if (avl >= CONF && avl - occ >= MARGIN) status = "free";
  if (!status) continue;               // ไม่มีหลักฐาน -> คงสถานะเดิม

  const key = cam + "-" + s.id;
  const st = states[key] || {cur: null, pend: status, since: Date.now()};
  if (status !== st.pend) { st.pend = status; st.since = Date.now(); }
  if (st.pend !== st.cur && Date.now() - st.since >= DEBOUNCE_MS) {
    st.cur = st.pend;
    out.push({
      topic: "parking/" + zone + "/slot/" + s.id,
      payload: {status: st.cur, type: s.type, cam: cam,
                conf: +Math.max(occ, avl).toFixed(2)},
      retain: true
    });
  }
  states[key] = st;
}
context.set("state", states);
return out.length ? [out] : null;

// กล้องหลุดรายตัว: ไม่มีเฟรมเกิน 10 วินาที -> ช่องของกล้องนั้นเป็น "unknown"
const CAMS = flow.get("CAMS");
if (!CAMS) return null;
const seen = flow.get("lastSeen") || {};
const off = flow.get("offline") || {};
const out = [];
for (const cam in seen) {
  if (Date.now() - seen[cam] > 10000 && !off[cam]) {
    off[cam] = true;
    for (const s of CAMS[cam]) {
      out.push({
        topic: "parking/" + cam.split("-")[0] + "/slot/" + s.id,
        payload: {status: "unknown", type: s.type, cam: cam, conf: null},
        retain: true
      });
    }
  }
}
flow.set("offline", off);
return out.length ? [out] : null;

// รวมสถานะทุกช่อง + บันทึกเหตุการณ์/ประวัติ
const id = msg.topic.split("/").pop();
const now = Date.now();
const st = flow.get("slotState") || {};
const prev = st[id] ? st[id].status : null;
const cur = msg.payload.status;
const prevTs = st[id] ? st[id].ts : now;
st[id] = Object.assign({}, msg.payload, {ts: now});
flow.set("slotState", st);
if (prev !== cur) {
  if (prev !== null) {
    const ev = flow.get("events") || [];
    ev.unshift({t: now, id: id, from: prev, to: cur});
    flow.set("events", ev.slice(0, 30));
  }
  // สถิติรายวัน
  const stats = flow.get("stats") || {};
  const today = new Date().toDateString();
  if (stats.day !== today) Object.assign(stats, {day: today, entries: 0, exits: 0, stays: [], peak: 0, peakT: null});
  if (prev === "free" && cur === "occupied") stats.entries++;
  if (prev === "occupied" && cur === "free") { stats.exits++; stats.stays.push(now - prevTs); stats.stays = stats.stays.slice(-200); }
  const occN = Object.values(st).filter(s => s.status === "occupied").length;
  if (occN > stats.peak) { stats.peak = occN; stats.peakT = now; }
  flow.set("stats", stats);
  const v = Object.values(st);
  const h = flow.get("history") || [];
  h.push({t: now, free: v.filter(s => s.status === "free").length, occ: occN});
  flow.set("history", h.slice(-300));
}
return {payload: st};

// ข้อมูลทั้งหมดสำหรับหน้า /parking
const CAMS = flow.get("CAMS") || {};
const LABEL = flow.get("LABEL") || {};
const seen = flow.get("lastSeen") || {}, off = flow.get("offline") || {};
const cstat = flow.get("camStats") || {};
const S = flow.get("slotState") || {};
const now = Date.now();
const cams = {};
let rec = null;
for (const c in CAMS) {
  const online = !!seen[c] && !off[c];
  const cs = cstat[c] || {};
  const free = CAMS[c].filter(s => S[s.id] && S[s.id].status === "free");
  cams[c] = {
    label: LABEL[c] || c,
    slots: CAMS[c].map(s => ({id: s.id, type: s.type, x1: s.x1, x2: s.x2, y1: s.y1, y2: s.y2})),
    online: online,
    // ช่องแบบ 2 มิติ (มี y1) -> บอกจำนวนคอลัมน์ให้ dashboard จัดเป็นตาราง
    cols: CAMS[c][0].y1 !== undefined ? new Set(CAMS[c].map(s => s.y1)).size : 0,   // 1 แถวในภาพ = 1 คอลัมน์บน dashboard (09-14 ซ้าย, 15-20 ขวา)
    age: seen[c] ? now - seen[c] : null,
    fps: online && cs.fps ? +cs.fps.toFixed(1) : 0,
    conf: cs.conf != null ? +cs.conf.toFixed(2) : null,
    ar: cs.ar || 16 / 9,
    boxes: online ? (cs.boxes || []) : []
  };
  // แนะนำ: ชั้นที่ออนไลน์และว่างมากที่สุด -> ช่องธรรมดาช่องแรกที่ว่าง
  const normal = free.filter(s => s.type !== "pwd");
  if (online && normal.length && (!rec || normal.length > rec.free))
    rec = {cam: c, label: cams[c].label, slot: normal[0].id, free: normal.length};
}
const st = flow.get("stats") || {};
const stays = st.stays || [];
msg.payload = {
  now: now, cams: cams, slots: S, rec: rec,
  events: flow.get("events") || [], history: flow.get("history") || [],
  stats: {entries: st.entries || 0, exits: st.exits || 0, peak: st.peak || 0, peakT: st.peakT || null,
          avgStay: stays.length ? Math.round(stays.reduce((a, b) => a + b, 0) / stays.length) : null}
};
return msg;

// สรุปจำนวนช่องว่างต่อชั้น -> ส่งให้ ESP32 บน Wokwi
const CAMS = flow.get("CAMS");
if (!CAMS) return null;
const S = flow.get("slotState") || {};
// เปลี่ยนชื่อชั้นตรงนี้ (ตอนนี้ 1 กล้อง = 1 ชั้น)
const LABEL = {"2A-C01": "Floor 1", "2A-C02": "Floor 2", "2A-C03": "Floor 3", "2A-C04": "Floor 4"};
const parts = [];
for (const cam in CAMS) {
  let free = 0, known = 0;
  // นับเฉพาะช่องธรรมดา: ช่องคนพิการ (pwd) ไม่นับเป็นที่ว่างสำหรับคนทั่วไป
  const normal = CAMS[cam].filter(s => s.type !== "pwd");
  for (const s of normal) {
    const st = S[s.id] && S[s.id].status;
    if (st === "free") free++;
    if (st === "free" || st === "occupied") known++;
  }
  parts.push((LABEL[cam] || cam) + "," + (known ? free : -1) + "," + normal.length);
}
return {topic: "cpe447-happywheel-7f3a/parking/summary", payload: parts.join(";"), retain: true};

// ส่งข้อมูลชุดเดียวกับ /api/state ขึ้น HiveMQ ให้หน้า dashboard บน Vercel
// ข้อมูลทั้งหมดสำหรับหน้า /parking
const CAMS = flow.get("CAMS") || {};
const LABEL = flow.get("LABEL") || {};
const seen = flow.get("lastSeen") || {}, off = flow.get("offline") || {};
const cstat = flow.get("camStats") || {};
const S = flow.get("slotState") || {};
const now = Date.now();
const cams = {};
let rec = null;
for (const c in CAMS) {
  const online = !!seen[c] && !off[c];
  const cs = cstat[c] || {};
  const free = CAMS[c].filter(s => S[s.id] && S[s.id].status === "free");
  cams[c] = {
    label: LABEL[c] || c,
    slots: CAMS[c].map(s => ({id: s.id, type: s.type, x1: s.x1, x2: s.x2, y1: s.y1, y2: s.y2})),
    online: online,
    // ช่องแบบ 2 มิติ (มี y1) -> บอกจำนวนคอลัมน์ให้ dashboard จัดเป็นตาราง
    cols: CAMS[c][0].y1 !== undefined ? new Set(CAMS[c].map(s => s.y1)).size : 0,   // 1 แถวในภาพ = 1 คอลัมน์บน dashboard (09-14 ซ้าย, 15-20 ขวา)
    age: seen[c] ? now - seen[c] : null,
    fps: online && cs.fps ? +cs.fps.toFixed(1) : 0,
    conf: cs.conf != null ? +cs.conf.toFixed(2) : null,
    ar: cs.ar || 16 / 9,
    boxes: online ? (cs.boxes || []) : []
  };
  // แนะนำ: ชั้นที่ออนไลน์และว่างมากที่สุด -> ช่องธรรมดาช่องแรกที่ว่าง
  const normal = free.filter(s => s.type !== "pwd");
  if (online && normal.length && (!rec || normal.length > rec.free))
    rec = {cam: c, label: cams[c].label, slot: normal[0].id, free: normal.length};
}
const st = flow.get("stats") || {};
const stays = st.stays || [];
msg.payload = {
  now: now, cams: cams, slots: S, rec: rec,
  events: (flow.get("events") || []).slice(0, 12), history: (flow.get("history") || []).slice(-90),
  stats: {entries: st.entries || 0, exits: st.exits || 0, peak: st.peak || 0, peakT: st.peakT || null,
          avgStay: stays.length ? Math.round(stays.reduce((a, b) => a + b, 0) / stays.length) : null}
};
msg.topic = "cpe447-happywheel-7f3a/parking/state";
msg.retain = true;
return msg;
